"""Compare claimed free-group words against every catalogued word.

Equivalences allowed (generous): cyclic rotation, reversal, inversion
(reverse + case swap), all 8 letter maps of the dihedral group on {a,A,b,B}
(a<->A, b<->B, a<->b and combinations), cyclic reduction (cancel xX pairs
cyclically), and also proper powers / roots (w == u^n).

Usage: python3 -I compare_words.py cat.json claims.json
"""
import sys, json, itertools

cat = json.load(open(sys.argv[1]))
claims = json.load(open(sys.argv[2]))

INV = {'a': 'A', 'A': 'a', 'b': 'B', 'B': 'b'}

# letter maps: generated by swapcase-a, swapcase-b, swap a<->b (letters).
def letter_maps():
    maps = []
    for swap_ab in (False, True):
        for ca in (False, True):
            for cb in (False, True):
                m = {}
                for x in 'aAbB':
                    y = x
                    if ca and y.lower() == 'a':
                        y = INV[y]
                    if cb and y.lower() == 'b':
                        y = INV[y]
                    if swap_ab:
                        y = {'a': 'b', 'A': 'B', 'b': 'a', 'B': 'A'}[y]
                    m[x] = y
                maps.append(m)
    return maps

MAPS = letter_maps()
assert len({tuple(sorted(m.items())) for m in MAPS}) == 8

def cyc_reduce(w):
    s = []
    for ch in w:
        if s and s[-1] == INV.get(ch):
            s.pop()
        else:
            s.append(ch)
    # cyclic
    while len(s) >= 2 and s[0] == INV.get(s[-1]):
        s = s[1:-1]
    return ''.join(s)

def primitive_root(w):
    n = len(w)
    for d in range(1, n + 1):
        if n % d == 0 and w[:d] * (n // d) == w:
            return w[:d], n // d
    return w, 1

def min_rot(w):
    if not w:
        return w
    return min(w[i:] + w[:i] for i in range(len(w)))

def canon(w):
    best = None
    for rev in (False, True):
        u = w[::-1] if rev else w
        for m in MAPS:
            v = ''.join(m[c] for c in u)
            r = min_rot(v)
            if best is None or r < best:
                best = r
    return best

def keys(w):
    """Set of canonical keys under all generous equivalences."""
    ks = set()
    for x in {w, cyc_reduce(w)}:
        root, p = primitive_root(x)
        ks.add(('full', canon(x)))
        ks.add(('root', canon(root)))
    return ks

# index catalogue
idx = {}
for r in cat:
    if 'word' not in r:
        continue
    w = r['word']
    if set(w) - set('aAbB'):
        print('WARN non-letter word', r['label'], w)
        continue
    for k in keys(w):
        idx.setdefault(k[1], []).append((k[0], r['file'], r['label'], len(w)))

print('catalogued words indexed:', sum(1 for r in cat if 'word' in r))

# also check for exact substring containment of the repeated core (aB)^k
for c in claims:
    w = c['word']
    hits = []
    for k in keys(w):
        for h in idx.get(k[1], []):
            hits.append((k[0],) + h)
    print('\n', c['id'], c['status'], 'word', w, 'L', len(w),
          'cycred', cyc_reduce(w) == w, 'primitive', primitive_root(w)[1] == 1)
    print('   canon', canon(w))
    if hits:
        for h in sorted(set(hits)):
            print('   MATCH', h)
    else:
        print('   no match')
